import os
from openai import OpenAI

client = OpenAI(
    api_key=os.environ.get("MIMO_API_KEY"),
    base_url="https://api.xiaomimimo.com/v1"
)

completion = client.chat.completions.create(
    model="mimo-v2.5-pro",
    messages=[
        {
            "role": "system",
            "content": "You are MiMo, an AI assistant developed by Xiaomi. Today is date: Tuesday, December 16, 2025. Your knowledge cutoff date is December 2024."
        },
        {
            "role": "user",
            "content": [
                {
                    "type": "text",
                    "text": "please introduce yourself"
                }
            ]
        }
    ],
    max_completion_tokens=1024,
    stream=True,
    extra_body={
        "thinking": {"type": "enabled"}
    }
)

for chunk in completion:
    print(chunk.model_dump_json())


Ez a kód egyszerre használja a stream=True és a "thinking": {"type": "enabled"} paramétereket egyazon hívásban. A válasz chunkonként érkezik vissza, és minden egyes chunkot a print(chunk.model_dump_json()) sor azonnal kiír – beleértve a gondolkodási (thinking) tokeneket és a végső szöveges válasz darabjait is.
